<?php $this->layout('default'); use Moves\Services\CmsSite; use Moves\Services\CmsQuery; use Moves\Support\CmsView as V; $locations = ['header' => 'Cabeçalho', 'footer' => 'Rodapé']; $edit = (int) V::queryString('editar') > 0 ? CmsQuery::one('SELECT * FROM cms_menu_items WHERE id=?', [(int) V::queryString('editar')]) : null; ?>
<div class="cms-form-list"><form class="cms-card" method="post" action="/acao/menu-save"><header class="cms-card-head"><div><h2><?= $edit ? 'Editar item' : 'Cadastrar item' ?></h2><small>Sem itens visíveis, o site mantém a navegação do template.</small></div><?= V::icon('menu') ?></header><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?: '' ?>"><input type="hidden" name="back" value="/menus"><div class="cms-form-grid"><?= V::field('Local', 'location', $edit['location'] ?? 'header', ['type' => 'select', 'choices' => $locations]) ?><?= V::field('Ordem', 'sort_order', $edit['sort_order'] ?? '0', ['type' => 'number']) ?></div><?= V::field('Rótulo', 'label', $edit['label'] ?? '', ['required' => true]) ?><?= V::field('Destino', 'url', $edit['url'] ?? '', ['required' => true, 'help' => 'Comece com / ou https://']) ?><?= V::field('Visível', 'is_visible', $edit['is_visible'] ?? '1', ['type' => 'checkbox']) ?><div class="cms-form-end"><button class="cms-btn-primary">Salvar item</button></div></form>
<div><?php foreach ($locations as $location => $name): $items = CmsSite::menu($location); ?><section class="cms-card"><header class="cms-card-head"><div><h2><?= V::e($name) ?></h2></div><b class="cms-count"><?= count($items) ?></b></header><?php if ($items === []): ?><?= V::empty('Sem itens neste local.') ?><?php endif; foreach ($items as $item): ?><div class="cms-row"><div><strong><?= V::e($item['label']) ?></strong> <?= $item['is_visible'] ? '' : V::badge('draft', 'Oculto') ?><br><code class="cms-chip"><?= V::e($item['url']) ?></code></div><div class="cms-td-actions"><?= V::iconLink('?editar=' . (int) $item['id'], 'Editar') ?><?= V::iconAction('menu-delete', 'Excluir', ['id' => $item['id']], 'Excluir este item?') ?></div></div><?php endforeach; ?></section><?php endforeach; ?></div></div>
